targets.expr:
sort_desc(
  (sum(rate(container_cpu_usage_seconds_total{namespace=~"voicegateway|cognigy-ai|monitoring", cluster="$cluster", pod!="", pod!~".*clean-up.*|.*audit-logs.*|.*update-api-ban.*|.*workload-restart.*"}[5m])) by (pod)
  /
  sum(cluster:namespace:pod_cpu:active:kube_pod_container_resource_limits{namespace=~"voicegateway|cognigy-ai|monitoring", cluster="$cluster", pod!="", pod!~".*clean-up.*|.*audit-logs.*|.*update-api-ban.*|.*workload-restart.*"}) by (pod)
  ) * 100
) > 100
